def _format_seconds(seconds: float) -> str:
    """Format seconds without float noise or exponent notation."""
    if seconds == int(seconds):
        return str(int(seconds))

    # Start with the shortest representation that round-trips exactly.  Then
    # replace it with a 15-significant-digit form only when that differs by at
    # most one ULP; this hides binary noise (e.g. 0.1 + 0.2 -> "0.3",
    # 1.5000000000000002 -> "1.5") without discarding meaningful precision.
    value = float(seconds)
    text = repr(value)
    candidate = f"{value:.15g}"
    try:
        if abs(float(candidate) - value) <= math.ulp(value):
            text = candidate
    except (OverflowError, ValueError):
        pass

    if "e" in text or "E" in text:
        text = f"{Decimal(text):f}"
    return text

