import itertools
import random
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, "/private/tmp/tmp5uk5a2ge/pete/projects/devkit")

from devkit.duration import Duration, format, parse

rng = random.Random(20261027)

# Random valid duration strings, including every subset/order of the grammar.
date_tokens = ["Y", "M", "W", "D"]
time_tokens = ["H", "M", "S"]
count = 0
for _ in range(2000):
    values = [rng.randint(0, 40) for _ in range(7)]
    use = [rng.random() < 0.6 for _ in range(7)]
    if not any(use):
        use[rng.randrange(7)] = True
    has_time = any(use[4:])
    if not any(use[:4]) and not has_time:
        use[0] = True
    text = "P"
    for token, value, present in zip(date_tokens, values[:4], use[:4]):
        if present:
            text += f"{value}{token}"
    if has_time:
        text += "T"
        for token, value, present in zip(time_tokens, values[4:], use[4:]):
            if present:
                if token == "S":
                    text += f"{value}.25S" if rng.random() < 0.4 else f"{value}S"
                else:
                    text += f"{value}{token}"
    duration = parse(text)
    parsed_again = parse(format(duration))
    assert parsed_again == duration, (text, duration, format(duration), parsed_again)
    formatted_once = format(duration)
    assert format(parsed_again) == formatted_once, (text, formatted_once)
    count += 1

# Every non-canonical zero/fraction variant normalizes.
for text in ["P0Y", "P0M", "P0W", "P0D", "PT0H", "PT0M", "PT0S",
             "P0YT0S", "PT000.500S", "P1DT00S", "P00Y00M00W00DT00H00M01.50S"]:
    assert parse(format(parse(text))) == parse(text), text
    count += 1

# Mutation checks: each single-token mutation is invalid.
tokens = ["1Y", "1M", "1W", "1D", "1H", "1M", "1S"]
valid = "P1Y2M3W4DT5H6M7S"
assert parse(valid) == Duration(1, 2, 3, 4, 5, 6, 7)
for index in range(len(valid)):
    broken = valid[:index] + valid[index + 1:]
    try:
        parse(broken)
    except ValueError:
        count += 1
    else:
        raise AssertionError(f"deletion {broken!r} unexpectedly parsed")

# Adjacent swaps that violate ordering.
for a, b in itertools.combinations(range(7), 2):
    pieces = ["1Y", "2M", "3W", "4D", "5H", "6M", "7S"]
    pieces[a], pieces[b] = pieces[b], pieces[a]
    text = "P" + "".join(pieces[:4]) + "T" + "".join(pieces[4:])
    if a < 4 <= b:
        # Moving a time piece before T or a date piece after T is invalid too.
        try:
            parse(text)
        except ValueError:
            count += 1
        else:
            raise AssertionError(f"swap {text!r} unexpectedly parsed")
    else:
        expected_invalid = False
        order_positions = list(range(7))
        order_positions[a], order_positions[b] = order_positions[b], order_positions[a]
        if order_positions != sorted(order_positions):
            expected_invalid = True
        if expected_invalid:
            try:
                parse(text)
            except ValueError:
                count += 1
            else:
                raise AssertionError(f"swap {text!r} unexpectedly parsed")

print(f"OK: {count} fuzz checks passed")

